let trans_cmd_brace_close ((kind, body) : mt) : CST.cmd_brace_close =
  match body with
  | Leaf v -> v
  | Children _ -> assert false

let trans_cond_qualified_op ((kind, body) : mt) : CST.cond_qualified_op =
  match body with
  | Leaf v -> v
  | Children _ -> assert false

let trans_imm_tok_hash ((kind, body) : mt) : CST.imm_tok_hash =
  match body with
  | Leaf v -> v
  | Children _ -> assert false

let trans_cmd_layout_start_let ((kind, body) : mt) : CST.cmd_layout_start_let =
  match body with
  | Leaf v -> v
