let trans_con_binding_list ((kind, body) : mt) : CST.con_binding_list =
  match body with
  | Children v ->
      (match v with
      | Seq [v0; v1] ->
          (
            (match v0 with
            | Alt (0, v) ->
                `Name (
                  trans_name (Run.matcher_token v)
                )
            | Alt (1, v) ->
                `Pcon (
                  trans_pconsym (Run.matcher_token v)
                )
            | _ -> assert false
            )
            ,
            Run.repeat1
              (fun v ->
                (match v with
                | Seq [v0; v1] ->
                    (
                      Run.trans_token (Run.matcher_token v0),
                      (match v1 with
                      | Alt (0, v) ->
                          `Name (
                            trans_name (Run.matcher_token v)
                          )
                      | Alt (1, v) ->
                          `Pcon (
                            trans_pconsym (Run.matcher_token v)
                          )
                      | _ -> assert false
                      )
                    )
                | _ -> assert false
                )
              )
              v1
          )
      | _ -> assert false
      )
  | Leaf _ -> assert false

