let trans_quasiquote ((kind, body) : mt) : CST.quasiquote =
  match body with
  | Children v ->
      (match v with
      | Seq [v0; v1; v2; v3; v4; v5] ->
          (
            trans_cond_quote_start (Run.matcher_token v0),
            Run.trans_token (Run.matcher_token v1),
            trans_quoter (Run.matcher_token v2),
            Run.trans_token (Run.matcher_token v3),
            Run.opt
              (fun v -> trans_quasiquote_body (Run.matcher_token v))
              v4
            ,
            (match v5 with
            | Alt (0, v) ->
                `Tok_barr (
                  trans_tok_barrbrack (Run.matcher_token v)
                )
            | Alt (1, v) ->
                `UNKUNKUNK (
                  Run.trans_token (Run.matcher_token v)
                )
            | _ -> assert false
            )
          )
      | _ -> assert false
      )
  | Leaf _ -> assert false

