let trans_ops ((kind, body) : mt) : CST.ops =
  match body with
  | Children v ->
      (match v with
      | Alt (0, v) ->
          `Op (
            trans_operator (Run.matcher_token v)
          )
      | Alt (1, v) ->
          `Qual_varsym (
            trans_qualified_varsym (Run.matcher_token v)
          )
      | Alt (2, v) ->
          `Cons_op (
            trans_constructor_operator (Run.matcher_token v)
          )
      | Alt (3, v) ->
          `Qual_consym (
            trans_qualified_consym (Run.matcher_token v)
          )
      | Alt (4, v) ->
          `Choice_choice_var_ticked (
            (match v with
            | Alt (0, v) ->
                `Choice_var_ticked (
                  (match v with
                  | Alt (0, v) ->
                      `Var_ticked (
                        trans_variable_ticked (Run.matcher_token v)
                      )
                  | Alt (1, v) ->
                      `Qvar_ticked (
                        trans_qvariable_ticked (Run.matcher_token v)
                      )
                  | _ -> assert false
                  )
                )
            | Alt (1, v) ->
                `Choice_cons_ticked (
                  (match v with
                  | Alt (0, v) ->
                      `Cons_ticked (
                        trans_constructor_ticked (Run.matcher_token v)
                      )
                  | Alt (1, v) ->
                      `Qcon_ticked (
                        trans_qconstructor_ticked (Run.matcher_token v)
                      )
                  | _ -> assert false
                  )
                )
            | _ -> assert false
            )
          )
      | _ -> assert false
      )
  | Leaf _ -> assert false

let trans_exp_op ((kind, body) : mt) : CST.exp_op =
  match body with
  | Children v ->
      (match v with
      | Alt (0, v) ->
