                )
            | _ -> assert false
            )
          )
      | Alt (1, v) ->
          `Choice_choice_var_ticked (
            (match v with
            | Alt (0, v) ->
                `Choice_var_ticked (
                  (match v with
                  | Alt (0, v) ->
                      `Var_ticked (
                        trans_variable_ticked (Run.matcher_token v)
                      )
                  | Alt (1, v) ->
                      `Qvar_ticked (
                        trans_qvariable_ticked (Run.matcher_token v)
                      )
                  | _ -> assert false
                  )
                )
            | Alt (1, v) ->
                `Choice_cons_ticked (
                  (match v with
                  | Alt (0, v) ->
                      `Cons_ticked (
                        trans_constructor_ticked (Run.matcher_token v)
                      )
                  | Alt (1, v) ->
                      `Qcon_ticked (
                        trans_qconstructor_ticked (Run.matcher_token v)
                      )
                  | _ -> assert false
                  )
                )
            | _ -> assert false
            )
          )
      | Alt (2, v) ->
          `Prefix_dot (
            trans_prefix_dot (Run.matcher_token v)
          )
      | _ -> assert false
      )
  | Leaf _ -> assert false





let trans_promoted_tycons_alias ((kind, body) : mt) : CST.promoted_tycons_alias =
  match body with
  | Children v ->
      (match v with
      | Seq [v0; v1] ->
