            | Alt (1, v) ->
                `Choice_qconid (
                  (match v with
                  | Alt (0, v) ->
                      `Qconid (
                        trans_qconid (Run.matcher_token v)
                      )
                  | Alt (1, v) ->
                      `Pqco (
                        trans_pqconsym (Run.matcher_token v)
                      )
