      )
  | Leaf _ -> assert false

let trans_role_annotation ((kind, body) : mt) : CST.role_annotation =
  match body with
  | Children v ->
      (match v with
      | Seq [v0; v1; v2; v3] ->
          (
            Run.trans_token (Run.matcher_token v0),
            Run.trans_token (Run.matcher_token v1),
            (match v2 with
            | Alt (0, v) ->
                `Choice_name (
                  (match v with
                  | Alt (0, v) ->
                      `Name (
                        trans_name (Run.matcher_token v)
                      )
                  | Alt (1, v) ->
                      `Pvar (
                        trans_pvarsym (Run.matcher_token v)
                      )
                  | Alt (2, v) ->
                      `Tycon_arrow (
                        trans_tycon_arrow (Run.matcher_token v)
                      )
                  | Alt (3, v) ->
                      `Pcon (
                        trans_pconsym (Run.matcher_token v)
                      )
                  | _ -> assert false
                  )
                )
            | Alt (1, v) ->
                `Choice_qtyc (
                  (match v with
                  | Alt (0, v) ->
                      `Qtyc (
                        trans_qtyconid (Run.matcher_token v)
                      )
                  | Alt (1, v) ->
                      `Qtycon_arrow (
                        trans_qtycon_arrow (Run.matcher_token v)
                      )
                  | Alt (2, v) ->
                      `Choice_pqva (
                        (match v with
                        | Alt (0, v) ->
                            `Pqva (
                              trans_pqvarsym (Run.matcher_token v)
                            )
                        | Alt (1, v) ->
                            `Pqco (
                              trans_pqconsym (Run.matcher_token v)
                            )
                        | _ -> assert false
                        )
                      )
                  | _ -> assert false
                  )
                )
            | _ -> assert false
            )
            ,
            Run.repeat1
              (fun v -> trans_type_role (Run.matcher_token v))
              v3
          )
      | _ -> assert false
      )
  | Leaf _ -> assert false





