          )
      | _ -> assert false
      )
  | Leaf _ -> assert false



let rec trans_alternative ((kind, body) : mt) : CST.alternative =
  match body with
  | Children v ->
      (match v with
      | Seq [v0; v1; v2] ->
          (
            trans_pat (Run.matcher_token v0),
            trans_matches (Run.matcher_token v1),
            Run.opt
              (fun v -> trans_where_binds (Run.matcher_token v))
              v2
          )
      | _ -> assert false
      )
  | Leaf _ -> assert false

and trans_alternatives ((kind, body) : mt) : CST.alternatives =
  match body with
  | Children v ->
      (match v with
      | Seq [v0; v1; v2] ->
          (
            (match v0 with
            | Alt (0, v) ->
                `Cmd_layout_start_case (
                  trans_cmd_layout_start_case (Run.matcher_token v)
                )
            | Alt (1, v) ->
                `Cmd_layout_start_expl (
                  trans_cmd_layout_start_explicit (Run.matcher_token v)
                )
            | _ -> assert false
            )
            ,
            Run.opt
              (fun v ->
                (match v with
                | Seq [v0; v1; v2; v3] ->
                    (
                      Run.opt
                        (fun v ->
                          (match v with
                          | Alt (0, v) ->
                              `Rep1_SEMI (
                                Run.repeat1
                                  (fun v -> Run.trans_token (Run.matcher_token v))
                                  v
                              )
                          | Alt (1, v) ->
                              `Cond_layout_semi (
                                trans_cond_layout_semicolon (Run.matcher_token v)
                              )
                          | _ -> assert false
                          )
                        )
                        v0
                      ,
                      trans_alternative (Run.matcher_token v1),
                      Run.repeat
                        (fun v ->
                          (match v with
                          | Seq [v0; v1] ->
