                    )
                | _ -> assert false
                )
              )
              v2
            ,
            Run.opt
              (fun v -> Run.trans_token (Run.matcher_token v))
              v3
            ,
            trans_bracket_close (Run.matcher_token v4)
          )
      | _ -> assert false
      )
  | Leaf _ -> assert false

