      | Seq [v0; v1; v2; v3] ->
          (
            trans_unboxed_open (Run.matcher_token v0),
            (match v1 with
            | Alt (0, v) ->
                `Rep1_choice_BAR_choice_view_pat (
                  (match v with
                  | Seq [v0; v1] ->
                      (
                        Run.repeat1
                          (fun v ->
                            (match v with
