                          v0
                        ,
                        (match v1 with
                        | Alt (0, v) ->
                            `View_pat (
                              trans_view_pattern (Run.matcher_token v)
                            )
                        | Alt (1, v) ->
                            `Pat (
                              trans_pat (Run.matcher_token v)
                            )
