                        )
                      )
                  | _ -> assert false
                  )
                )
            | Alt (1, v) ->
                `Choice_view_pat_choice_BAR (
                  (match v with
                  | Seq [v0; v1] ->
                      (
                        (match v0 with
                        | Alt (0, v) ->
                            `View_pat (
                              trans_view_pattern (Run.matcher_token v)
                            )
                        | Alt (1, v) ->
                            `Pat (
                              trans_pat (Run.matcher_token v)
