                        | Alt (1, v) ->
                            `Imm_tok_bar (
                              trans_imm_tok_bar (Run.matcher_token v)
                            )
                        | _ -> assert false
                        )
                      )
                  | _ -> assert false
                  )
                )
            | _ -> assert false
            )
            ,
            Run.repeat
              (fun v ->
                (match v with
                | Alt (0, v) ->
                    `BAR (
                      Run.trans_token (Run.matcher_token v)
                    )
                | Alt (1, v) ->
                    `Imm_tok_bar (
                      trans_imm_tok_bar (Run.matcher_token v)
                    )
                | _ -> assert false
                )
              )
              v2
            ,
            trans_unboxed_close (Run.matcher_token v3)
          )
      | _ -> assert false
      )
  | Leaf _ -> assert false

