and trans_patsyn_cons ((kind, body) : mt) : CST.patsyn_cons =
  match body with
  | Children v ->
      (match v with
      | Seq [v0; v1; v2] ->
          (
            (match v0 with
            | Alt (0, v) ->
                `Cmd_layout_start (
                  trans_cmd_layout_start (Run.matcher_token v)
                )
            | Alt (1, v) ->
                `Cmd_layout_start_expl (
                  trans_cmd_layout_start_explicit (Run.matcher_token v)
                )
            | _ -> assert false
            )
            ,
            Run.opt
              (fun v ->
                (match v with
                | Seq [v0; v1; v2; v3] ->
                    (
                      Run.opt
                        (fun v ->
                          (match v with
                          | Alt (0, v) ->
                              `Rep1_SEMI (
                                Run.repeat1
                                  (fun v -> Run.trans_token (Run.matcher_token v))
                                  v
                              )
                          | Alt (1, v) ->
                              `Cond_layout_semi (
                                trans_cond_layout_semicolon (Run.matcher_token v)
                              )
                          | _ -> assert false
                          )
                        )
                        v0
                      ,
                      trans_bind (Run.matcher_token v1),
                      Run.repeat
                        (fun v ->
                          (match v with
                          | Seq [v0; v1] ->
                              (
                                (match v0 with
                                | Alt (0, v) ->
                                    `Rep1_SEMI (
                                      Run.repeat1
                                        (fun v -> Run.trans_token (Run.matcher_token v))
                                        v
                                    )
                                | Alt (1, v) ->
                                    `Cond_layout_semi (
                                      trans_cond_layout_semicolon (Run.matcher_token v)
                                    )
                                | _ -> assert false
                                )
                                ,
                                trans_bind (Run.matcher_token v1)
                              )
                          | _ -> assert false
                          )
                        )
                        v2
                      ,
                      Run.opt
                        (fun v ->
                          (match v with
                          | Alt (0, v) ->
                              `Rep1_SEMI (
                                Run.repeat1
                                  (fun v -> Run.trans_token (Run.matcher_token v))
                                  v
                              )
                          | Alt (1, v) ->
                              `Cond_layout_semi (
                                trans_cond_layout_semicolon (Run.matcher_token v)
                              )
                          | _ -> assert false
                          )
                        )
                        v3
                    )
                | _ -> assert false
                )
              )
              v1
            ,
            trans_layout_end (Run.matcher_token v2)
          )
      | _ -> assert false
      )
  | Leaf _ -> assert false

