          )
      | _ -> assert false
      )
  | Leaf _ -> assert false

and trans_patsyn_signature ((kind, body) : mt) : CST.patsyn_signature =
  match body with
  | Children v ->
      (match v with
      | Seq [v0; v1; v2] ->
          (
            (match v0 with
            | Alt (0, v) ->
                `Choice_name (
                  (match v with
                  | Alt (0, v) ->
                      `Name (
                        trans_name (Run.matcher_token v)
                      )
                  | Alt (1, v) ->
                      `Pcon (
                        trans_pconsym (Run.matcher_token v)
                      )
                  | _ -> assert false
                  )
                )
            | Alt (1, v) ->
                `Con_bind_list (
                  trans_con_binding_list (Run.matcher_token v)
                )
            | _ -> assert false
            )
            ,
            trans_colon2 (Run.matcher_token v1),
            trans_quantified_type (Run.matcher_token v2)
          )
      | _ -> assert false
      )
  | Leaf _ -> assert false

and trans_pattern ((kind, body) : mt) : CST.pattern =
  match body with
  | Children v ->
      (match v with
      | Alt (0, v) ->
          `Pat_infix (
            trans_pat_infix (Run.matcher_token v)
          )
      | Alt (1, v) ->
          `Pat_nega (
            trans_pat_negation (Run.matcher_token v)
          )
      | Alt (2, v) ->
          `Pat_apply (
            trans_pat_apply (Run.matcher_token v)
          )
      | Alt (3, v) ->
          `Choice_choice_var (
            (match v with
            | Alt (0, v) ->
                `Choice_var (
                  (match v with
                  | Alt (0, v) ->
                      `Var (
                        trans_variable (Run.matcher_token v)
                      )
                  | Alt (1, v) ->
                      `Pvar (
                        trans_pvarsym (Run.matcher_token v)
                      )
                  | _ -> assert false
                  )
                )
            | Alt (1, v) ->
                `Choice_choice_name (
                  (match v with
                  | Alt (0, v) ->
                      `Choice_name (
                        (match v with
                        | Alt (0, v) ->
                            `Name (
                              trans_name (Run.matcher_token v)
                            )
                        | Alt (1, v) ->
                            `Pcon (
                              trans_pconsym (Run.matcher_token v)
                            )
                        | _ -> assert false
                        )
                      )
                  | Alt (1, v) ->
                      `Choice_qconid (
                        (match v with
                        | Alt (0, v) ->
                            `Qconid (
                              trans_qconid (Run.matcher_token v)
                            )
                        | Alt (1, v) ->
                            `Pqco (
                              trans_pqconsym (Run.matcher_token v)
                            )
                        | _ -> assert false
                        )
                      )
                  | _ -> assert false
                  )
                )
            | _ -> assert false
            )
          )
      | Alt (4, v) ->
          `Pat_as (
            trans_pat_as (Run.matcher_token v)
          )
      | Alt (5, v) ->
          `Pat_record (
            trans_pat_record (Run.matcher_token v)
          )
      | Alt (6, v) ->
          `Pat_wild (
            trans_pat_wildcard (Run.matcher_token v)
          )
      | Alt (7, v) ->
          `Pat_parens (
            trans_pat_parens (Run.matcher_token v)
          )
      | Alt (8, v) ->
          `Pat_tuple (
            trans_pat_tuple (Run.matcher_token v)
          )
      | Alt (9, v) ->
          `Pat_unbo_tuple (
            trans_pat_unboxed_tuple (Run.matcher_token v)
          )
      | Alt (10, v) ->
          `Pat_unbo_sum (
            trans_pat_unboxed_sum (Run.matcher_token v)
          )
      | Alt (11, v) ->
          `Pat_list (
            trans_pat_list (Run.matcher_token v)
          )
      | Alt (12, v) ->
          `Plist (
            trans_plist (Run.matcher_token v)
          )
      | Alt (13, v) ->
          `Pat_strict (
            trans_pat_strict (Run.matcher_token v)
          )
      | Alt (14, v) ->
          `Pat_irre (
            trans_pat_irrefutable (Run.matcher_token v)
          )
      | Alt (15, v) ->
          `Choice_splice (
            (match v with
            | Alt (0, v) ->
                `Splice (
                  trans_splice (Run.matcher_token v)
                )
            | Alt (1, v) ->
                `Quas (
                  trans_quasiquote (Run.matcher_token v)
                )
            | Alt (2, v) ->
                `Lit (
                  trans_literal (Run.matcher_token v)
                )
            | Alt (3, v) ->
                `Choice_unit (
                  (match v with
                  | Alt (0, v) ->
                      `Unit (
                        trans_unit_ (Run.matcher_token v)
                      )
                  | Alt (1, v) ->
                      `Unbo_unit (
                        trans_unboxed_unit (Run.matcher_token v)
                      )
                  | _ -> assert false
                  )
                )
            | Alt (4, v) ->
                `Choice_prefix_tuple (
                  (match v with
                  | Alt (0, v) ->
                      `Prefix_tuple (
                        trans_prefix_tuple (Run.matcher_token v)
                      )
                  | Alt (1, v) ->
                      `Prefix_unbo_tuple (
                        trans_prefix_unboxed_tuple (Run.matcher_token v)
                      )
                  | Alt (2, v) ->
                      `Prefix_unbo_sum (
                        trans_prefix_unboxed_sum (Run.matcher_token v)
                      )
                  | _ -> assert false
                  )
                )
            | _ -> assert false
            )
          )
      | _ -> assert false
      )
  | Leaf _ -> assert false

