                      trans_ktype (Run.matcher_token v1)
                    )
                | _ -> assert false
                )
              )
              v2
            ,
            trans_unboxed_close (Run.matcher_token v3)
          )
      | _ -> assert false
      )
  | Leaf _ -> assert false

and trans_type_unboxed_tuple ((kind, body) : mt) : CST.type_unboxed_tuple =
  match body with
  | Children v ->
      (match v with
      | Seq [v0; v1; v2; v3] ->
          (
            trans_unboxed_open (Run.matcher_token v0),
            trans_ktype (Run.matcher_token v1),
            Run.repeat
              (fun v ->
                (match v with
                | Seq [v0; v1] ->
                    (
                      Run.trans_token (Run.matcher_token v0),
                      trans_ktype (Run.matcher_token v1)
                    )
                | _ -> assert false
                )
              )
              v2
            ,
            trans_unboxed_close (Run.matcher_token v3)
          )
      | _ -> assert false
      )
  | Leaf _ -> assert false

and trans_via ((kind, body) : mt) : CST.via =
  match body with
  | Children v ->
      (match v with
      | Seq [v0; v1] ->
          (
            Run.trans_token (Run.matcher_token v0),
            trans_quantified_type (Run.matcher_token v1)
          )
      | _ -> assert false
      )
  | Leaf _ -> assert false

and trans_view_pattern ((kind, body) : mt) : CST.view_pattern =
  match body with
  | Children v ->
      (match v with
      | Seq [v0; v1; v2] ->
          (
            trans_exp (Run.matcher_token v0),
            trans_arrow (Run.matcher_token v1),
            (match v2 with
            | Alt (0, v) ->
                `View_pat (
                  trans_view_pattern (Run.matcher_token v)
                )
            | Alt (1, v) ->
                `Pat (
                  trans_pat (Run.matcher_token v)
                )
            | _ -> assert false
            )
          )
      | _ -> assert false
      )
  | Leaf _ -> assert false

and trans_where_binds ((kind, body) : mt) : CST.where_binds =
  match body with
  | Children v ->
      (match v with
      | Seq [v0; v1] ->
          (
            trans_where (Run.matcher_token v0),
            Run.opt
              (fun v -> trans_local_binds (Run.matcher_token v))
              v1
          )
      | _ -> assert false
      )
  | Leaf _ -> assert false

let trans_children ((kind, body) : mt) : CST.children =
  match body with
  | Children v ->
      (match v with
      | Seq [v0; v1; v2] ->
          (
            trans_paren_open (Run.matcher_token v0),
            Run.opt
              (fun v ->
                (match v with
                | Seq [v0; v1] ->
                    (
                      (match v0 with
                      | Alt (0, v) ->
                          `DOTDOT (
                            Run.trans_token (Run.matcher_token v)
                          )
                      | Alt (1, v) ->
                          `Child (
                            trans_child (Run.matcher_token v)
                          )
                      | _ -> assert false
                      )
                      ,
                      Run.repeat
                        (fun v ->
                          (match v with
                          | Seq [v0; v1] ->
                              (
                                Run.trans_token (Run.matcher_token v0),
                                (match v1 with
                                | Alt (0, v) ->
                                    `DOTDOT (
                                      Run.trans_token (Run.matcher_token v)
                                    )
                                | Alt (1, v) ->
                                    `Child (
                                      trans_child (Run.matcher_token v)
                                    )
                                | _ -> assert false
                                )
                              )
                          | _ -> assert false
                          )
                        )
                        v1
                    )
                | _ -> assert false
                )
              )
              v1
            ,
            trans_paren_close (Run.matcher_token v2)
          )
      | _ -> assert false
      )
  | Leaf _ -> assert false
















let trans_ie_entity ((kind, body) : mt) : CST.ie_entity =
  match body with
  | Children v ->
      (match v with
      | Seq [v0; v1; v2] ->
          (
            Run.opt
              (fun v -> trans_namespace (Run.matcher_token v))
              v0
            ,
            (match v1 with
            | Alt (0, v) ->
                `Choice_qvarid (
                  (match v with
                  | Alt (0, v) ->
                      `Qvarid (
                        trans_qvarid (Run.matcher_token v)
                      )
                  | Alt (1, v) ->
                      `Var (
                        trans_variable (Run.matcher_token v)
                      )
                  | _ -> assert false
                  )
                )
            | Alt (1, v) ->
                `Choice_qtyc (
                  (match v with
                  | Alt (0, v) ->
                      `Qtyc (
                        trans_qtyconid (Run.matcher_token v)
                      )
                  | Alt (1, v) ->
                      `Name (
                        trans_name (Run.matcher_token v)
                      )
                  | _ -> assert false
                  )
                )
            | Alt (2, v) ->
                `Choice_sym_prefix (
                  (match v with
                  | Alt (0, v) ->
                      `Sym_prefix (
                        trans_sym_prefix (Run.matcher_token v)
                      )
                  | Alt (1, v) ->
                      `Choice_pqva (
                        (match v with
                        | Alt (0, v) ->
                            `Pqva (
                              trans_pqvarsym (Run.matcher_token v)
                            )
                        | Alt (1, v) ->
                            `Pqco (
                              trans_pqconsym (Run.matcher_token v)
                            )
                        | _ -> assert false
                        )
                      )
                  | _ -> assert false
                  )
                )
            | _ -> assert false
            )
            ,
            Run.opt
              (fun v -> trans_children (Run.matcher_token v))
              v2
          )
      | _ -> assert false
      )
  | Leaf _ -> assert false

let trans_exports ((kind, body) : mt) : CST.exports =
  match body with
  | Children v ->
      (match v with
      | Seq [v0; v1; v2; v3] ->
          (
            trans_paren_open (Run.matcher_token v0),
            Run.opt
              (fun v ->
                (match v with
                | Seq [v0; v1] ->
                    (
                      (match v0 with
                      | Alt (0, v) ->
                          `Ie_entity (
                            trans_ie_entity (Run.matcher_token v)
                          )
                      | Alt (1, v) ->
                          `Module_export (
                            trans_module_export (Run.matcher_token v)
                          )
                      | _ -> assert false
                      )
                      ,
                      Run.repeat
                        (fun v ->
                          (match v with
                          | Seq [v0; v1] ->
                              (
                                Run.trans_token (Run.matcher_token v0),
                                (match v1 with
                                | Alt (0, v) ->
                                    `Ie_entity (
                                      trans_ie_entity (Run.matcher_token v)
                                    )
                                | Alt (1, v) ->
                                    `Module_export (
                                      trans_module_export (Run.matcher_token v)
                                    )
                                | _ -> assert false
                                )
                              )
                          | _ -> assert false
                          )
                        )
                        v1
                    )
                | _ -> assert false
                )
              )
              v1
            ,
            Run.opt
              (fun v -> Run.trans_token (Run.matcher_token v))
              v2
            ,
            trans_paren_close (Run.matcher_token v3)
          )
      | _ -> assert false
      )
  | Leaf _ -> assert false

let trans_import_list ((kind, body) : mt) : CST.import_list =
  match body with
  | Children v ->
      (match v with
      | Seq [v0; v1; v2; v3] ->
          (
            trans_paren_open (Run.matcher_token v0),
            Run.opt
              (fun v ->
                (match v with
                | Seq [v0; v1] ->
                    (
                      trans_ie_entity (Run.matcher_token v0),
