                        (fun v ->
                          (match v with
                          | Seq [v0; v1] ->
                              (
                                Run.trans_token (Run.matcher_token v0),
                                trans_ie_entity (Run.matcher_token v1)
                              )
                          | _ -> assert false
                          )
                        )
                        v1
                    )
                | _ -> assert false
                )
              )
              v1
            ,
            Run.opt
              (fun v -> Run.trans_token (Run.matcher_token v))
              v2
            ,
            trans_paren_close (Run.matcher_token v3)
          )
      | _ -> assert false
      )
  | Leaf _ -> assert false

let trans_header ((kind, body) : mt) : CST.header =
  match body with
  | Children v ->
      (match v with
      | Seq [v0; v1; v2; v3] ->
          (
            Run.trans_token (Run.matcher_token v0),
            trans_module_ (Run.matcher_token v1),
            Run.opt
              (fun v -> trans_exports (Run.matcher_token v))
              v2
            ,
            trans_where (Run.matcher_token v3)
          )
      | _ -> assert false
      )
  | Leaf _ -> assert false

let trans_import ((kind, body) : mt) : CST.import =
  match body with
  | Children v ->
      (match v with
      | Seq [v0; v1; v2; v3; v4; v5; v6] ->
          (
            Run.trans_token (Run.matcher_token v0),
            Run.opt
              (fun v -> Run.trans_token (Run.matcher_token v))
              v1
            ,
            Run.opt
              (fun v -> trans_string_ (Run.matcher_token v))
              v2
            ,
            trans_module_ (Run.matcher_token v3),
            Run.opt
              (fun v -> Run.trans_token (Run.matcher_token v))
              v4
            ,
            Run.opt
              (fun v ->
                (match v with
                | Seq [v0; v1] ->
                    (
                      Run.trans_token (Run.matcher_token v0),
                      trans_module_ (Run.matcher_token v1)
                    )
                | _ -> assert false
                )
              )
              v5
            ,
            Run.opt
              (fun v ->
                (match v with
                | Seq [v0; v1] ->
                    (
                      Run.opt
                        (fun v -> Run.trans_token (Run.matcher_token v))
                        v0
                      ,
                      trans_import_list (Run.matcher_token v1)
                    )
                | _ -> assert false
                )
              )
              v6
          )
      | _ -> assert false
      )
  | Leaf _ -> assert false

let trans_imports ((kind, body) : mt) : CST.imports =
  match body with
  | Children v ->
      (match v with
      | Seq [v0; v1; v2] ->
          (
            trans_import (Run.matcher_token v0),
            Run.repeat
              (fun v ->
                (match v with
                | Seq [v0; v1] ->
                    (
                      (match v0 with
                      | Alt (0, v) ->
                          `Rep1_SEMI (
                            Run.repeat1
                              (fun v -> Run.trans_token (Run.matcher_token v))
                              v
                          )
                      | Alt (1, v) ->
                          `Cond_layout_semi (
                            trans_cond_layout_semicolon (Run.matcher_token v)
                          )
                      | _ -> assert false
                      )
                      ,
                      trans_import (Run.matcher_token v1)
                    )
                | _ -> assert false
                )
              )
              v1
            ,
            (match v2 with
            | Alt (0, v) ->
                `Rep1_SEMI (
                  Run.repeat1
                    (fun v -> Run.trans_token (Run.matcher_token v))
                    v
                )
            | Alt (1, v) ->
                `Cond_layout_semi (
                  trans_cond_layout_semicolon (Run.matcher_token v)
                )
            | _ -> assert false
            )
          )
      | _ -> assert false
      )
  | Leaf _ -> assert false

let trans_declarations ((kind, body) : mt) : CST.declarations =
  match body with
  | Children v ->
      (match v with
      | Seq [v0; v1; v2] ->
          (
            trans_declaration (Run.matcher_token v0),
            Run.repeat
              (fun v ->
                (match v with
                | Seq [v0; v1] ->
                    (
                      (match v0 with
                      | Alt (0, v) ->
                          `Rep1_SEMI (
                            Run.repeat1
                              (fun v -> Run.trans_token (Run.matcher_token v))
                              v
                          )
                      | Alt (1, v) ->
                          `Cond_layout_semi (
                            trans_cond_layout_semicolon (Run.matcher_token v)
                          )
                      | _ -> assert false
                      )
                      ,
                      (match v1 with
                      | Alt (0, v) ->
                          `Decl (
                            trans_declaration (Run.matcher_token v)
                          )
                      | Alt (1, v) ->
                          `Import (
                            trans_import (Run.matcher_token v)
                          )
                      | _ -> assert false
                      )
                    )
                | _ -> assert false
                )
              )
              v1
            ,
            Run.opt
              (fun v ->
                (match v with
                | Alt (0, v) ->
                    `Rep1_SEMI (
                      Run.repeat1
                        (fun v -> Run.trans_token (Run.matcher_token v))
                        v
                    )
                | Alt (1, v) ->
                    `Cond_layout_semi (
                      trans_cond_layout_semicolon (Run.matcher_token v)
                    )
                | _ -> assert false
                )
              )
              v2
          )
      | _ -> assert false
      )
  | Leaf _ -> assert false

let trans_body ((kind, body) : mt) : CST.body =
  match body with
  | Children v ->
      (match v with
      | Seq [v0; v1; v2; v3; v4] ->
          (
            (match v0 with
            | Alt (0, v) ->
                `Cmd_layout_start (
                  trans_cmd_layout_start (Run.matcher_token v)
                )
            | Alt (1, v) ->
                `Cmd_layout_start_expl (
                  trans_cmd_layout_start_explicit (Run.matcher_token v)
                )
            | _ -> assert false
            )
            ,
            Run.opt
              (fun v ->
                (match v with
                | Alt (0, v) ->
                    `Rep1_SEMI (
                      Run.repeat1
                        (fun v -> Run.trans_token (Run.matcher_token v))
                        v
                    )
                | Alt (1, v) ->
                    `Cond_layout_semi (
                      trans_cond_layout_semicolon (Run.matcher_token v)
                    )
                | _ -> assert false
                )
              )
              v1
            ,
            Run.opt
              (fun v -> trans_imports (Run.matcher_token v))
              v2
            ,
            Run.opt
              (fun v -> trans_declarations (Run.matcher_token v))
              v3
            ,
            trans_layout_end (Run.matcher_token v4)
          )
      | _ -> assert false
      )
  | Leaf _ -> assert false

let trans_haskell ((kind, body) : mt) : CST.haskell =
  match body with
  | Children v ->
      (match v with
      | Seq items ->
          (* Tree-sitter-haskell original returns direct children: header?, imports?, declarations?
             Instead of trying to match semgrep-haskell's complex body structure,
             we accept any sequence and return (None, None) to let Haskell_to_generic
             handle the conversion directly from tree-sitter nodes *)
          Printf.eprintf "[trans_haskell] Got %d children, returning stub CST for direct tree-sitter conversion\n%!" (List.length items);
          (None, None)
      | _ ->
          Printf.eprintf "[trans_haskell] Non-Seq structure, returning (None, None)\n%!";
          (None, None)
      )
  | Leaf _ ->
      Printf.eprintf "[trans_haskell] Leaf node, returning (None, None)\n%!";
      (None, None)

(*
   Costly operation that translates a whole tree or subtree.

   The first pass translates it into a generic tree structure suitable
   to guess which node corresponds to each grammar rule.
   The second pass is a translation into a typed tree where each grammar
   node has its own type.

   This function is called:
   - once on the root of the program after removing extras
     (comments and other nodes that occur anywhere independently from
     the grammar);
   - once of each extra node, resulting in its own independent tree of type
     'extra'.
*)
let translate_tree src node trans_x =
  Printf.eprintf "[TRANSLATE_TREE] Matching node type: %s\n%!" node.Tree_sitter_output_t.type_;
  let matched_tree = Run.match_tree children_regexps src node in
  Printf.eprintf "[TRANSLATE_TREE] Match result: %s\n%!" (match matched_tree with Some _ -> "Some" | None -> "None");
  (match matched_tree with
   | None ->
       Printf.eprintf "[TRANSLATE_TREE] Failed to match, node has %d children\n%!"
         (match node.Tree_sitter_output_t.children with Some c -> List.length c | None -> 0);
       (match node.Tree_sitter_output_t.children with
        | Some children when List.length children <= 10 ->
            List.iteri (fun i child ->
              Printf.eprintf "[TRANSLATE_TREE]   Child %d: %s\n%!" i child.Tree_sitter_output_t.type_
            ) children
        | _ -> ())
   | Some _ -> ());
  Option.map trans_x matched_tree


let translate_extra src (node : Tree_sitter_output_t.node) : CST.extra option =
  match node.type_ with
  | "cpp" ->
      (match translate_tree src node trans_cpp with
      | None -> None
      | Some x -> Some (`Cpp (Run.get_loc node, x)))
  | "comment" ->
      (match translate_tree src node trans_comment with
      | None -> None
      | Some x -> Some (`Comment (Run.get_loc node, x)))
  | "haddock" ->
      (match translate_tree src node trans_haddock with
      | None -> None
      | Some x -> Some (`Haddock (Run.get_loc node, x)))
  | "pragma" ->
      (match translate_tree src node trans_pragma with
      | None -> None
      | Some x -> Some (`Pragma (Run.get_loc node, x)))
  | _ -> None

let translate_root src root_node =
  translate_tree src root_node trans_haskell

let parse_input_tree input_tree =
  let orig_root_node = Tree_sitter_parsing.root input_tree in
  let src = Tree_sitter_parsing.src input_tree in
  Printf.eprintf "[PARSE.ML] Root node type: %s\n%!" orig_root_node.Tree_sitter_output_t.type_;
  (match orig_root_node.Tree_sitter_output_t.children with
   | Some children ->
       Printf.eprintf "[PARSE.ML] Root node children count: %d\n%!" (List.length children);
       List.iteri (fun i child ->
         Printf.eprintf "[PARSE.ML]   Child %d type: %s\n%!" i child.Tree_sitter_output_t.type_
       ) children
   | None ->
       Printf.eprintf "[PARSE.ML] Root node has NO children\n%!");
  let errors = Run.extract_errors src orig_root_node in
  Printf.eprintf "[PARSE.ML] Errors extracted: %d\n%!" (List.length errors);
  (if errors <> [] then
    List.iter (fun err ->
      Printf.eprintf "[PARSE.ML] Error: %s\n%!" err.Tree_sitter_run.Tree_sitter_error.msg
    ) errors);
  let opt_program, extras =
     Run.translate
       ~extras
       ~translate_root:(translate_root src)
       ~translate_extra:(translate_extra src)
       orig_root_node
  in
  Printf.eprintf "[PARSE.ML] After translate: opt_program=%s\n%!" (match opt_program with Some _ -> "Some" | None -> "None");
  Parsing_result.create src opt_program extras errors

let string ?src_file contents =
  let input_tree = parse_source_string ?src_file contents in
  parse_input_tree input_tree

let file src_file =
  let input_tree = parse_source_file src_file in
  parse_input_tree input_tree

